def transform(grid):
    a = [row[:] for row in grid]
    # The repeated V motifs have a vertical bridge between their left centers,
    # and a horizontal bridge between the opposing lower arms.
    for r in range(len(a)):
        if r+2 < len(a) and a[r][2] == 2 and a[r+2][2] == 2 and all(a[r+1][c] == 0 for c in (1,2,3)):
            a[r+1][2] = 1
    for r, row in enumerate(a):
        cs = [c for c, v in enumerate(row) if v == 2]
        if len(cs) >= 4 and cs[-1]-cs[0] >= 8:
            for c in range(cs[1]+1, cs[-2]):
                if a[r][c] == 0: a[r][c] = 1
    return a
